import React, { useState } from 'react';
import {
  ScrollView,
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Dimensions
} from 'react-native';
import axios from 'axios';
import {
  VictoryChart,
  VictoryLine,
  VictoryTheme,
  VictoryAxis
} from 'victory';    // <--- import web

export default function DetailScreen({ route }) {
  const { sensor, apiUrl } = route.params;
  const [history, setHistory] = useState(sensor.history || []);

  const fetchHistory = async () => {
    try {
      const response = await axios.get(`${apiUrl}/sensors/${sensor.id}`);
      setHistory(response.data.history);
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <ScrollView style={styles.screen} contentContainerStyle={{ padding: 16 }}>
      <View style={styles.card}>
        <Text style={styles.title}>Histórico de {sensor.name}</Text>
        <View style={styles.chartContainer}>
          <VictoryChart
            theme={VictoryTheme.material}
            domainPadding={20}
            width={Dimensions.get('window').width - 64}
            height={200}
          >
            <VictoryAxis tickFormat={(t) => `#${t}`} />
            <VictoryAxis dependentAxis />
            <VictoryLine
              animate={{ duration: 500 }}
              data={history.map((v, i) => ({ x: i + 1, y: v }))}
              style={{ data: { stroke: '#007AFF' } }}
            />
          </VictoryChart>
        </View>
      </View>

      <TouchableOpacity style={styles.button} onPress={fetchHistory}>
        <Text style={styles.buttonText}>ATUALIZAR</Text>
      </TouchableOpacity>
    </ScrollView>
  );
}

